import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CuR1irRm.js";var i=JSON.parse(`{"title":"Model providers: OpenRouter and OpenCode","description":"","frontmatter":{"authorship":["ai"]},"headers":[],"relativePath":"services/ai/model-providers.md","filePath":"services/ai/model-providers.md"}`),a={name:`services/ai/model-providers.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1794665063000`},[...i[0]||=[e(`<h1 id="model-providers-openrouter-and-opencode" tabindex="-1">Model providers: OpenRouter and OpenCode <a class="header-anchor" href="#model-providers-openrouter-and-opencode" aria-label="Permalink to “Model providers: OpenRouter and OpenCode”">​</a></h1><p>Notopia already uses <code>@ai-sdk/openai-compatible</code> to call a model over HTTP. Switching a compatible provider requires configuration, not a new chat implementation.</p><p>Three values select the model, in <code>apps/ai/.env.local</code>:</p><div class="language-dotenv" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_BASE_URL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">https://provider.example/v1</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_API_KEY</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">replace-with-your-provider-key</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_MODEL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">replace-with-a-provider-model-id</span></span></code></pre></div><p>The base URL is the API prefix, without <code>/chat/completions</code>. The service calls the provider&#39;s Chat Completions API and streams tool calls. Choose a model supporting that API, streaming and tools. A Responses-only or Anthropic-only endpoint is not interchangeable with this adapter. Keep keys server-side in the ignored local file, and restart <code>nx run ai:run</code> after changes.</p><h2 id="what-the-names-mean" tabindex="-1">What the names mean <a class="header-anchor" href="#what-the-names-mean" aria-label="Permalink to “What the names mean”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Role in this setup</th></tr></thead><tbody><tr><td>Notopia AI service</td><td>Runs Notopia&#39;s chat/tool loop, permissions and credit accounting</td></tr><tr><td>OpenRouter</td><td>Hosted gateway offering many models through one API</td></tr><tr><td>OpenCode Console (formerly Zen)</td><td>Hosted model API that can also supply models to Notopia</td></tr><tr><td>OpenCode coding agent</td><td>Separate development tool for working on this repository</td></tr></tbody></table><p>Using OpenCode&#39;s model API does not run the coding agent inside Notopia. Conversely, using OpenCode to develop the repository does not configure the application&#39;s model credentials.</p><h2 id="option-1-openrouter" tabindex="-1">Option 1: OpenRouter <a class="header-anchor" href="#option-1-openrouter" aria-label="Permalink to “Option 1: OpenRouter”">​</a></h2><ol><li>Create an <a href="https://openrouter.ai/settings/keys" target="_blank" rel="noreferrer">OpenRouter API key</a>.</li><li>Choose a model from the <a href="https://openrouter.ai/models" target="_blank" rel="noreferrer">catalog</a> that supports tool calling.</li><li>Create or update <code>apps/ai/.env.local</code>:</li></ol><div class="language-dotenv" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_BASE_URL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">https://openrouter.ai/api/v1</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_API_KEY</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">replace-with-your-openrouter-key</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_MODEL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">openrouter/free</span></span></code></pre></div><p><code>openrouter/free</code> routes among available free models, accounting for the request&#39;s supported features. It is useful for trying the integration, but model availability, rate limits and behavior can vary. For repeatable editing tests, choose a specific tool-capable model ID from the catalog instead. Free usage is still subject to OpenRouter&#39;s account/provider limits.</p><p>No OpenRouter SDK or special provider headers are required by the current service. The existing adapter sends the API key as Bearer authentication.</p><p>Official references:</p><ul><li><a href="https://openrouter.ai/docs/quickstart" target="_blank" rel="noreferrer">OpenRouter quickstart</a></li><li><a href="https://openrouter.ai/docs/guides/routing/routers/free-router" target="_blank" rel="noreferrer">Free model router</a></li></ul><h2 id="option-2-opencode-s-hosted-model-api" tabindex="-1">Option 2: OpenCode&#39;s hosted model API <a class="header-anchor" href="#option-2-opencode-s-hosted-model-api" aria-label="Permalink to “Option 2: OpenCode&#39;s hosted model API”">​</a></h2><p>OpenCode&#39;s hosted offering was called <strong>Zen</strong>; current documentation describes it as <strong>OpenCode Console</strong>. Use its inference API directly, without starting an OpenCode server.</p><ol><li>Sign in to the <a href="https://opencode.ai/console" target="_blank" rel="noreferrer">OpenCode Console</a>, configure account access and create an API key.</li><li>Choose an available model that supports Chat Completions and tools from the <a href="https://opencode.ai/docs/console/models/" target="_blank" rel="noreferrer">model documentation</a>.</li><li>Configure <code>apps/ai/.env.local</code>, for example:</li></ol><div class="language-dotenv" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_BASE_URL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">https://opencode.ai/inference/openai/v1</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_API_KEY</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">replace-with-your-opencode-console-key</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_MODEL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">glm-5.3</span></span></code></pre></div><p>This uses a paid-model example from the current catalog; availability and account access may change. Use the provider&#39;s bare model ID (<code>glm-5.3</code>), not the coding agent&#39;s <code>opencode/glm-5.3</code> selection string.</p><p>Current OpenCode documentation restricts free-tier chat models to the OpenCode application; other clients can receive <code>403</code> even with a key. Notopia is another client, so use a paid model or eligible Go subscription access rather than assuming an OpenCode free model will work.</p><p>Older examples use <code>https://opencode.ai/zen/v1</code>; use the currently documented inference base URL for new configurations. This service does not consume the OpenCode session/server API, and its own <code>/ai</code> endpoint is not an OpenAI-compatible provider endpoint for OpenCode.</p><h2 id="optional-use-the-opencode-coding-agent-with-openrouter" tabindex="-1">Optional: use the OpenCode coding agent with OpenRouter <a class="header-anchor" href="#optional-use-the-opencode-coding-agent-with-openrouter" aria-label="Permalink to “Optional: use the OpenCode coding agent with OpenRouter”">​</a></h2><p>This configures your development tool, independently of the Notopia runtime:</p><ol><li>Start OpenCode in the repository.</li><li>Run <code>/connect</code>, select OpenRouter and enter your OpenRouter key.</li><li>Run <code>/models</code> and choose a model available to that account.</li></ol><p>OpenCode model selection adds a provider prefix to the full provider model ID. For example, the following optional <code>opencode.json</code> setting selects the OpenRouter free router:</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">{</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">  &quot;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">$schema</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;https://opencode.ai/config.json&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">  &quot;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">model</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;openrouter/openrouter/free&quot;</span></span>
<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">}</span></span></code></pre></div><p>The double <code>openrouter</code> is intentional: the first identifies OpenCode&#39;s provider; the remaining <code>openrouter/free</code> is OpenRouter&#39;s model ID. In Notopia&#39;s <code>.env.local</code>, use only <code>openrouter/free</code>. OpenCode can also read <code>OPENROUTER_API_KEY</code> from its process environment; Notopia instead reads <code>NOTOPIA_AI_LLM_API_KEY</code>. Neither automatically reads the other&#39;s login.</p><p>See <a href="https://opencode.ai/docs/providers/#openrouter" target="_blank" rel="noreferrer">OpenCode provider setup</a>.</p><h2 id="option-3-local-ollama" tabindex="-1">Option 3: local Ollama <a class="header-anchor" href="#option-3-local-ollama" aria-label="Permalink to “Option 3: local Ollama”">​</a></h2><p>The checked-in <code>apps/ai/.env</code> defaults to Ollama:</p><div class="language-dotenv" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_BASE_URL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">http://localhost:11434/v1</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_API_KEY</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">ollama</span></span>
<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">NOTOPIA_AI_LLM_MODEL</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">qwen3:8b</span></span></code></pre></div><p>If Ollama is not already running on the host, use the optional Compose profile:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">docker</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> compose</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -f</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> deploy/compose/compose.yaml</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --profile</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai-local-llm</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> up</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -d</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --wait</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai_ollama</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">docker</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> compose</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -f</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> deploy/compose/compose.yaml</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --profile</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai-local-llm</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> exec</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai_ollama</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ollama</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pull</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> qwen3:8b</span></span></code></pre></div><p>The container runs on CPU by default and stores models in a named volume. Do not start it on port <code>11434</code> if a host Ollama process already uses that port. Remove or update conflicting provider overrides in <code>.env.local</code> when switching back to local inference.</p><h2 id="verify-the-complete-integration" tabindex="-1">Verify the complete integration <a class="header-anchor" href="#verify-the-complete-integration" aria-label="Permalink to “Verify the complete integration”">​</a></h2><p>Provider configuration only supplies model access. Follow <a href="./index.html#local-setup">local setup</a> to start Redis, the application services and web, and use a workspace with AI credits.</p><p>Verify all three behaviors:</p><ol><li>A simple prompt streams a text response.</li><li>A note question invokes search/read tools and returns authorized workspace content.</li><li>An editing request opens a note, applies suggestions in the live editor, and supports Accept/Discard followed by a separate Commit.</li></ol><p>A successful text response does not establish tool compatibility. Likewise, provider credits and Notopia workspace AI credits are independent checks. These examples document the integration configuration; they do not assert a live provider smoke test has passed.</p>`,40)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};